<!doctype html><html><head><meta charset="utf-8"></head><body style="font-family:Arial,sans-serif;color:#20392f;line-height:1.7;max-width:660px;margin:20px auto"><h1 style="font-size:24px">{{$subject}}</h1>@if($payload['type']==='invoice')<p>Your invoice {{$payload['number']}} is ready. Review the services, agreed terms and deposit or full-payment instructions.</p><p><a href="{{$payload['url']}}">View your private invoice</a></p><p>This link expires after {{config('tourism.document_link_hours')}} hours. Contact the operator if you need a new link.</p>@elseif($payload['type']==='payment')<p>A verified {{$payload['kind']}} of {{$payload['currency']}} {{$payload['amount']}} has been recorded for invoice {{$payload['number']}}. Your private invoice shows the updated payment ledger and remaining balance.</p>@elseif($payload['type']==='contact')<p>{{$payload['name']}} · {{$payload['email']}}</p><p style="white-space:pre-line">{{$payload['message']}}</p>@else<p>Reference: <strong>{{$booking?->reference}}</strong></p>@if($payload['type']==='confirmation')<p>Your booking has been confirmed under the agreed arrangements. Please contact our team about any remaining travel details.</p>@else<p>Your request has been received. Our team will review availability and send the final price and payment instructions. Reservation confirmation will follow after the arrangements are agreed.</p>@endif @if($booking)<p>{{$booking->name}} · {{$booking->start_date->format('d M Y')}} to {{$booking->end_date->format('d M Y')}}<br>{{$booking->adults}} adult(s), {{$booking->children}} child(ren)</p><ul>@foreach($booking->items as $item)<li>{{$item->description}} · {{$item->quantity}} {{str_replace('_',' ',$item->unit)}} · {{$item->amount===null?'Pending quotation':\App\Support\Money::format($item->amount,$booking->currency)}}</li>@endforeach</ul><p>Known services subtotal: {{\App\Support\Money::format($booking->known_subtotal,$booking->currency)}}</p>@if($booking->transport)<p>Transfer: {{$booking->transport->snapshot['origin']}} to {{$booking->transport->snapshot['destination']}}<br>{{$booking->transport->snapshot['vehicle']}} · {{$booking->transport->passengers}} passengers<br>Pickup {{$booking->transport->pickup_at->timezone('Africa/Dar_es_Salaam')->format('d M Y H:i')}} (UTC+3)<br>{{$booking->transport->pickup_details}} → {{$booking->transport->dropoff_details}}</p>@endif @if($booking->accommodation)<h2 style="font-size:17px">Accommodation preferences</h2><ul>@foreach($booking->accommodation->preferences as $key=>$value)@if(!str_ends_with($key,'_id'))<li>{{ucwords(str_replace('_',' ',$key))}}: {{is_array($value)?implode(', ',$value):$value}}</li>@endif @endforeach</ul>@if($payload['type']==='confirmation' && $booking->accommodation->selectedProposal)<p>Hotel: {{$booking->accommodation->selectedProposal->hotel_name}}<br>Reservation reference: {{$booking->accommodation->selectedProposal->supplier_reference}}</p>@endif @endif @if(($payload['audience']??'customer')==='admin')<p>Contact: {{$booking->email}} / {{$booking->phone}}<br>Review this request in your staff dashboard.</p>@endif @endif @endif<p style="font-size:12px;color:#68786f">{{$site['company_name']??'Sparkling Tours and Safaris'}}</p></body></html>
